import fs from "fs";
import path from "path";
import os from "os";
import zlib from "zlib";

const root = path.join(os.homedir(), ".dsh/sessions");
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);

function* frames(buf) {
  let i = 0;
  while (i < buf.length) {
    const j = buf.indexOf(MAGIC, i);
    if (j < 0) break;
    let k = j + 4;
    while (k < buf.length) {
      const next = buf.indexOf(MAGIC, k);
      const slice = next < 0 ? buf.subarray(j) : buf.subarray(j, next);
      try {
        yield zlib.zstdDecompressSync(slice).toString("utf8");
      } catch {}
      if (next < 0) break;
      i = next;
      break;
    }
    if (k >= buf.length) break;
  }
}

function scanFile(fp) {
  const buf = fs.readFileSync(fp);
  let text = "";
  for (const chunk of frames(buf)) text += chunk + "\n";
  if (!text) return null;
  const hits = {
    openviking_context: (text.match(/openviking-context/gi) || []).length,
    mcp__openviking: (text.match(/mcp__openviking__/g) || []).length,
    viking:\/\/: (text.match(/viking:\/\//g) || []).length,
    remember: (text.match(/"toolName":"remember"|mcp__openviking__remember/g) || []).length,
    search: (text.match(/mcp__openviking__search|mcp__openviking__find/g) || []).length,
    dsh_memory_plugin: (text.match(/dsh-memory-plugin|openviking-memory/gi) || []).length,
  };
  const total = Object.values(hits).reduce((a, b) => a + b, 0);
  if (!total) return null;
  return { fp, ...hits, total };
}

const files = [];
function walk(dir, depth = 0) {
  if (depth > 4) return;
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walk(p, depth + 1);
    else if (ent.name === "session.v4.jsonl.zstd") files.push(p);
  }
}
walk(root);
files.sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs);

const rows = [];
for (const fp of files.slice(0, 40)) {
  try {
    const r = scanFile(fp);
    if (r) rows.push({ mtime: fs.statSync(fp).mtime.toISOString().slice(0, 16), ...r });
  } catch {}
}
rows.sort((a, b) => b.mtime.localeCompare(a.mtime));
console.log(JSON.stringify(rows.slice(0, 15), null, 2));
console.log("scanned", files.length, "logs, hits", rows.length);
